#include "sector_leader_store.hpp"
#include "sector_observation_restore.hpp"
#include <QFile>
#include <QUrl>
#include <QThread>
#include <QSqlDatabase>
#include <QSqlQuery>
#include <QFileInfo>
#include <QDir>
#include <QJsonDocument>
#include <QUuid>
#include <QTemporaryFile>
#include <QRegularExpression>
#include <stdexcept>
namespace sectorLeader {namespace {
void need(bool ok,const char* message="人工观察库操作失败；原记录保留"){if(!ok)throw std::runtime_error(message);}
void active(const Cancel& cancel){need(!cancel||!cancel(),"人工观察操作已取消");}
qint64 scalar(QSqlDatabase& db,QString sql){QSqlQuery q(db);need(q.exec(sql)&&q.next());return q.value(0).toLongLong();}
void exec(QSqlDatabase& db,QString sql){QSqlQuery q(db);need(q.exec(sql));}
struct Connection {
 QString name=QUuid::createUuid().toString();QSqlDatabase db=QSqlDatabase::addDatabase("QSQLITE",name);
 Connection(QString file,bool write,const Cancel& cancel){try{active(cancel);if(write&&!QFileInfo::exists(file))need(QDir().mkpath(QFileInfo(file).absolutePath()));db.setDatabaseName(file);db.setConnectOptions(write?"QSQLITE_BUSY_TIMEOUT=100":"QSQLITE_OPEN_READONLY;QSQLITE_BUSY_TIMEOUT=100");need(db.open());auto app=scalar(db,"PRAGMA application_id");need(app==0x534c5631||(write&&app==0&&scalar(db,"SELECT count(*) FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")==0),"不是人工龙头专用库，未改动");need(scalar(db,"PRAGMA user_version")<=1,"人工观察库版本过高");if(write){exec(db,"PRAGMA synchronous=FULL");need(db.transaction());try{exec(db,"CREATE TABLE IF NOT EXISTS config(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL,digest TEXT NOT NULL,payload BLOB NOT NULL)");exec(db,"CREATE TABLE IF NOT EXISTS observations(id TEXT PRIMARY KEY,sector_id TEXT NOT NULL,captured_at TEXT NOT NULL,digest TEXT NOT NULL,payload BLOB NOT NULL)");exec(db,"CREATE INDEX IF NOT EXISTS observation_sector_time ON observations(sector_id,captured_at DESC,id)");exec(db,"CREATE TABLE IF NOT EXISTS imports(digest TEXT PRIMARY KEY,applied_at TEXT NOT NULL)");exec(db,"PRAGMA application_id=1397511729");exec(db,"PRAGMA user_version=1");active(cancel);need(db.commit());}catch(...){db.rollback();throw;}}}catch(...){close();throw;}}
 void close(){db.close();db={};QSqlDatabase::removeDatabase(name);}~Connection(){close();}
};
struct Transaction {QSqlDatabase& db;bool committed=false;explicit Transaction(QSqlDatabase& d):db(d){need(db.transaction());}~Transaction(){if(!committed)db.rollback();}void commit(const Cancel& cancel){active(cancel);need(db.commit());committed=true;}};
QJsonObject payload(QSqlQuery& q,int max){need(q.value(1).toLongLong()>0&&q.value(1).toLongLong()<=max,"人工观察数据长度无效");auto bytes=q.value(0).toByteArray();need(hash(bytes)==q.value(2).toString(),"人工观察摘要不符");QJsonParseError error;auto doc=QJsonDocument::fromJson(bytes,&error);need(error.error==QJsonParseError::NoError&&doc.isObject(),"人工观察JSON损坏");return doc.object();}
QJsonObject config(QSqlDatabase& db){QSqlQuery q(db);need(q.exec("SELECT CASE WHEN length(payload)<=2097152 THEN payload ELSE NULL END,length(payload),digest,revision FROM config WHERE id=1"));if(!q.next())return empty();auto c=payload(q,2097152);validate(c);need(c["revision"].toDouble()==q.value(3).toLongLong(),"人工配置版本不符");return c;}
QJsonObject write(QSqlDatabase& db,QJsonObject input,qint64 expected,const Cancel& cancel){validate(input);need(expected>=0&&expected<9007199254740991LL,"人工配置版本超范围");need(config(db)["revision"].toDouble()==expected,"人工稿已被修改，请重新读取后保存");input["revision"]=double(expected+1);input["updatedAt"]=QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs);validate(input);auto bytes=QJsonDocument(input).toJson(QJsonDocument::Compact);QSqlQuery q(db);q.prepare("INSERT OR REPLACE INTO config(id,revision,digest,payload) VALUES(1,?,?,?)");q.addBindValue(expected+1);q.addBindValue(hash(bytes));q.addBindValue(bytes);need(q.exec());need(config(db)==input,"人工稿写后读回不符");active(cancel);return input;}
}
QJsonObject Store::read(const Cancel& cancel)const{active(cancel);if(!QFileInfo::exists(file))return empty();Connection c(file,false,cancel);auto out=config(c.db);active(cancel);return out;}
QJsonObject Store::save(QJsonObject input,qint64 expected,const Cancel& cancel)const{validate(input);active(cancel);Connection c(file,true,cancel);Transaction tx(c.db);auto out=write(c.db,input,expected,cancel);tx.commit(cancel);return out;}
QJsonObject Store::importPreview(QJsonObject p,const Cancel& cancel)const{need(QRegularExpression("^[0-9a-f]{64}$").match(p["digest"].toString()).hasMatch(),"导入摘要错误");validate(p["config"].toObject());Connection c(file,true,cancel);Transaction tx(c.db);QSqlQuery check(c.db);check.prepare("SELECT 1 FROM imports WHERE digest=?");check.addBindValue(p["digest"].toString());need(check.exec());if(check.next()){auto out=config(c.db);tx.commit(cancel);return out;}auto out=write(c.db,p["config"].toObject(),qint64(p["expectedRevision"].toDouble(-1)),cancel);QSqlQuery q(c.db);q.prepare("INSERT INTO imports(digest,applied_at) VALUES(?,?)");q.addBindValue(p["digest"].toString());q.addBindValue(QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs));need(q.exec());tx.commit(cancel);return out;}
void Store::saveShot(QJsonObject shot,const Cancel& cancel)const{validateShot(shot);need(shot["schema"]==shotSchema,"旧观察只能按原来源迁入，不能补造冻结版本");Connection c(file,true,cancel);Transaction tx(c.db);need(config(c.db)["revision"]==shot["configRevision"],"人工名单版本已变化，请重新冻结观察");need(scalar(c.db,"SELECT count(*) FROM observations WHERE json_extract(CAST(payload AS TEXT),'$.schema')!='native-sector-leader-legacy-observation/v1'")<legacy::nativeLimit,"历史已达2000条，请明确清理后保存");auto bytes=QJsonDocument(shot).toJson(QJsonDocument::Compact);QSqlQuery q(c.db);q.prepare("INSERT INTO observations(id,sector_id,captured_at,digest,payload) VALUES(?,?,?,?,?)");q.addBindValue(shot["id"].toString());q.addBindValue(shot["sectorId"].toString());q.addBindValue(shot["capturedAt"].toString());q.addBindValue(hash(bytes));q.addBindValue(bytes);need(q.exec());tx.commit(cancel);}
QJsonArray Store::history(QString id,int offset,int limit,const Cancel& cancel)const{need(offset>=0&&offset<=legacy::totalLimit&&limit>=1&&limit<=100,"历史分页超范围");active(cancel);QJsonArray out;if(!QFileInfo::exists(file))return out;Connection c(file,false,cancel);QSqlQuery q(c.db);q.prepare("SELECT CASE WHEN length(payload)<=8388608 THEN payload ELSE NULL END,length(payload),digest FROM observations WHERE sector_id=? ORDER BY captured_at DESC,id DESC LIMIT ? OFFSET ?");q.addBindValue(id);q.addBindValue(limit);q.addBindValue(offset);need(q.exec());while(q.next()){active(cancel);auto s=payload(q,8388608);validateShot(s);need(s["sectorId"]==id,"历史板块身份不符");out.append(s);}return out;}
QJsonArray Store::historyBoards(const Cancel& cancel)const{active(cancel);QJsonArray out;if(!QFileInfo::exists(file))return out;Connection c(file,false,cancel);QSqlQuery q(c.db);need(q.exec("SELECT sector_id,count(*) FROM observations GROUP BY sector_id ORDER BY max(captured_at) DESC"));while(q.next()){active(cancel);out.append(QJsonObject{{"id",q.value(0).toString()},{"count",q.value(1).toInt()}});}return out;}
QJsonObject Store::trend(QString id,QString leaderId,QString fullId,const Cancel& cancel)const{active(cancel);QJsonArray nativeRows,oldRows;int nativeCount=0,oldCount=0;if(QFileInfo::exists(file)){Connection c(file,false,cancel);QSqlQuery q(c.db);q.prepare("SELECT CASE WHEN length(payload)<=8388608 THEN payload ELSE NULL END,length(payload),digest FROM observations WHERE sector_id=? ORDER BY captured_at DESC,id DESC");q.addBindValue(id);need(q.exec());while(q.next()){active(cancel);auto s=payload(q,8388608);validateShot(s);need(s["sectorId"]==id,"历史板块身份不符");for(auto v:s["rows"].toArray()){auto r=v.toObject();if(r["id"]!=leaderId||r["fullId"].toString()!=fullId)continue;bool old=legacy::isShot(s);auto& rows=old?oldRows:nativeRows;auto& count=old?oldCount:nativeCount;++count;if(rows.isEmpty()||(rows.size()==1&&r["change"].isDouble()))rows.append(QJsonObject{{"capturedAt",s["capturedAt"]},{"rows",QJsonArray{r}}});}}}auto out=sectorLeader::trend(nativeRows,leaderId,fullId);out["samples"]=nativeCount;if(oldCount){auto old=sectorLeader::trend(oldRows,leaderId,fullId);old["samples"]=oldCount;old["historicalConfigAvailable"]=false;old["timezone"]="unrecorded";out["legacyHistory"]=old;}out["mixedTimeDomains"]=oldCount>0&&nativeCount>0;active(cancel);return out;}
int Store::count(QString id,const Cancel& cancel)const{active(cancel);if(!QFileInfo::exists(file))return 0;Connection c(file,false,cancel);QSqlQuery q(c.db);q.prepare("SELECT count(*) FROM observations WHERE sector_id=?");q.addBindValue(id);need(q.exec()&&q.next());return q.value(0).toInt();}
int Store::prune(QString id,int keep,int expectedCount,const Cancel& cancel)const{need(keep>=1&&keep<=legacy::totalLimit,"保留数必须为1至8000");Connection c(file,true,cancel);Transaction tx(c.db);QSqlQuery domains(c.db);domains.prepare("SELECT count(DISTINCT CASE WHEN json_extract(CAST(payload AS TEXT),'$.schema')='native-sector-leader-legacy-observation/v1' THEN 'legacy' ELSE 'native' END) FROM observations WHERE sector_id=?");domains.addBindValue(id);need(domains.exec()&&domains.next()&&domains.value(0).toInt()<=1,"同板块同时含未知时区旧记录与原生冻结，不能按混合时序清理；原记录保留");domains.finish();QSqlQuery q(c.db);q.prepare("SELECT count(*) FROM observations WHERE sector_id=?");q.addBindValue(id);need(q.exec()&&q.next());need(q.value(0).toInt()==expectedCount,"历史已变化，请重新预览清理");q.finish();q.prepare("DELETE FROM observations WHERE id IN (SELECT id FROM observations WHERE sector_id=? ORDER BY captured_at DESC,id DESC LIMIT -1 OFFSET ?)");q.addBindValue(id);q.addBindValue(keep);need(q.exec());tx.commit(cancel);return qMax(0,expectedCount-keep);}
void exportNew(QByteArray bytes,const QString& path,const Cancel& cancel){active(cancel);QFileInfo target(path);need(!target.exists()&&!target.isSymLink()&&QFileInfo(target.absolutePath()).isDir(),"仅允许新文件，不覆盖既有文件");QTemporaryFile temp(target.absolutePath()+"/.leader-export-XXXXXX");need(temp.open()&&temp.write(bytes)==bytes.size()&&temp.flush(),"导出写入失败");temp.close();active(cancel);need(!QFileInfo::exists(path)&&temp.rename(target.absoluteFilePath()),"目标已存在或发布失败");temp.setAutoRemove(false);}
}
